"use client";

import { usePathname } from "next/navigation";
import { findNavArea } from "@/components/nav-groups";

// Zeigt in der Kopfzeile, wo man gerade ist ("Programm / Veranstaltungen"),
// statt eines statischen Untertitels. Generated by Claude Code.
export function DashboardBreadcrumb() {
  const pathname = usePathname();
  const match = findNavArea(pathname);

  return (
    <nav aria-label="Pfad" className="flex min-w-0 items-center gap-2 text-[13px]">
      <span className="text-[#6B6B6B]">{match?.group.label ?? "Redaktion"}</span>
      {match && (
        <>
          <span aria-hidden="true" className="text-[#BDBDBD]">/</span>
          <span key={match.area.href} className="fw-fade truncate font-medium text-[#111111]">
            {match.area.label}
          </span>
        </>
      )}
    </nav>
  );
}
